import {extractiveAnswer} from './retrieval.mjs';
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={home:'M3 11 12 3l9 8M5 10v11h14V10M9 21v-8h6v8',spark:'m12 3 2.8 6.2L21 12l-6.2 2.8L12 21l-2.8-6.2L3 12l6.2-2.8L12 3',grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',file:'M14 2H5v20h14V7l-5-5M14 2v6h5M8 12h8M8 16h6',activity:'M2 12h5l3-8 4 16 3-8h5',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1 1-3',arrow:'M5 12h14M13 6l6 6-6 6',up:'M12 19V5M6 11l6-6 6 6',chevron:'m9 5 7 7-7 7',down:'m6 9 6 6 6-6',plus:'M12 5v14M5 12h14',search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14m5 12 6 6',mic:'M9 5a3 3 0 0 1 6 0v7a3 3 0 0 1-6 0V5M5 10v2a7 7 0 0 0 14 0v-2M12 19v3M8 22h8',pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 0 1 16 0M12 7a3 3 0 1 0 0 6 3 3 0 0 0 0-6',bed:'M3 18v3M21 18v3M3 18h18V9H3v9M5 9V4h14v5M7 13h3M14 13h3',area:'M3 9V3h6M15 3h6v6M21 15v6h-6M9 21H3v-6',heart:'M12 21 3 12a6 6 0 0 1 9-8 6 6 0 0 1 9 8l-9 9',shield:'m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6l9-4m-4 10 3 3 5-6',check:'m5 12 4 4L19 6',close:'m6 6 12 12M6 18 18 6',upload:'M12 16V3M6 9l6-6 6 6M4 16v5h16v-5',download:'M12 3v13M6 10l6 6 6-6M4 17v4h16v-4',book:'M12 5C8 2 5 2 2 3v17c3-1 6-1 10 1 4-2 7-2 10-1V3c-3-1-6-1-10 2v16',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18m0 4v6l4 2',trash:'M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7M14 10v7',volume:'M3 9h5l5-5v16l-5-5H3V9m14-2c3 3 3 7 0 10m3-13c5 5 5 11 0 16',help:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18m-3 5a3 3 0 0 1 6 0c0 2-3 2-3 5m0 3v1',menu:'M4 6h16M4 12h16M4 18h16',link:'M9 15 15 9m-6-3 3-3a5 5 0 0 1 7 7l-3 3m-1 5-3 3a5 5 0 0 1-7-7l3-3',stop:'M6 6h12v12H6z',code:'m8 5-7 7 7 7m8-14 7 7-7 7m-3-16-2 18'};
const icon=(name,size=20)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.file}"/></svg>`;
const money=n=>'₹'+Number(n).toLocaleString('en-IN');
const uid=()=>crypto.randomUUID?.()||Array.from(crypto.getRandomValues(new Uint8Array(16)),v=>v.toString(16).padStart(2,'0')).join('');
const state={view:location.hash.slice(1)||'assistant',property:'canopy',properties:[],documents:[],chats:{},traces:[],favorites:[],mode:'demo',health:null,base:'',session:uid(),busy:false,recording:false,voice:false,query:'',beds:'all',docFilter:'all',current:null};
let db,ws,wsPromise,toastTimer,audioContext,micStream,worklet,captureTimer,lastSpeech,heardSpeech=false,activeAudio;
const persisted=()=>({properties:state.properties,documents:state.documents,chats:state.chats,traces:state.traces,favorites:state.favorites,property:state.property});
function save(){if(state.mode!=='demo'||!db)return;const tx=db.transaction('state','readwrite');tx.objectStore('state').put(persisted(),'workspace');tx.onerror=()=>toast('Browser storage is full. Export your conversation and remove unused documents.');}
async function initStorage(){try{db=await new Promise((resolve,reject)=>{const req=indexedDB.open('haven-v1',1);req.onupgradeneeded=()=>req.result.createObjectStore('state');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});return await new Promise(resolve=>{const r=db.transaction('state').objectStore('state').get('workspace');r.onsuccess=()=>resolve(r.result);r.onerror=()=>resolve(null);});}catch{return null;}}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4500);}
function prop(id=state.property){return state.properties.find(p=>p.id===id)||state.properties[0];}
function docCount(id){return state.documents.filter(d=>!id||d.property_id===id).length;}
function badge(){return state.mode==='demo'?'<span class="mode-badge"><i></i> Sample workspace</span>':'<span class="mode-badge live"><i></i> Local backend connected</span>';}
function changeView(view){if(!['assistant','properties','knowledge','activity','settings'].includes(view))view='assistant';state.view=view;state.query='';location.hash=view;render();}
function render(){
  const links=[['assistant','spark','Assistant'],['properties','grid','Properties'],['knowledge','book','Knowledge base'],['activity','activity','Activity']];
  $('#app').innerHTML=`<aside class="sidebar"><a href="#assistant" class="brand" data-nav="assistant"><span class="brand-icon">${icon('home',25)}</span><span>haven<span class="brand-dot">.</span></span></a><div class="workspace-label">YOUR WORKSPACE</div><nav>${links.map(([id,ic,title])=>`<button class="nav-item ${state.view===id?'active':''}" data-nav="${id}">${icon(ic)}<span>${title}</span>${['properties','knowledge'].includes(id)?`<span class="nav-count">${id==='properties'?state.properties.length:state.documents.length}</span>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="local-card"><span class="local-emblem">${icon('shield',19)}</span><strong>Thoughtfully local.</strong><p>Your knowledge. Your space.<br>No paid API required.</p><button data-nav="settings">Explore your setup ${icon('arrow',15)}</button></div><button class="nav-item ${state.view==='settings'?'active':''}" data-nav="settings">${icon('settings')}<span>Settings & setup</span></button><div class="profile"><span class="avatar">PM</span><div><strong>Parth’s workspace</strong><small>Personal · Local-first</small></div></div></div></aside><div class="main-shell"><header class="topbar"><button class="icon-btn mobile-menu" data-action="menu" aria-label="Toggle navigation">${icon('menu')}</button><div class="breadcrumb">Workspace ${icon('chevron',13)} <strong>${{assistant:'Assistant',properties:'Properties',knowledge:'Knowledge base',activity:'Activity',settings:'Settings & setup'}[state.view]}</strong></div><div class="top-actions">${badge()}<span class="top-divider"></span><button class="icon-btn" data-action="guide" aria-label="Getting started">${icon('help')}</button><span class="avatar small">PM</span></div></header><main id="main">${viewHTML()}</main><footer class="app-footer"><span>${icon('shield',13)} A little more clarity. A lot more confidence.</span><span>Haven <span class="footer-dot">·</span> Real estate intelligence</span></footer></div>`;
  if(state.view==='assistant')scrollChat();
}
function viewHTML(){return {assistant:assistantView,properties:propertiesView,knowledge:knowledgeView,activity:activityView,settings:settingsView}[state.view]?.()||assistantView();}
function header(eyebrow,title,description,action=''){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${description}</p></div>${action}</div>`;}
function assistantView(){const p=prop();const messages=state.chats[state.property]||[];return `${header('A SPACE FOR BETTER DECISIONS','Your property knowledge,<br><span>in conversation.</span>','From the first question to the fine print. Make yourself at home.','<button class="subtle-btn" data-action="new-chat">'+icon('plus',16)+' New conversation</button>')}<div class="assistant-layout"><section class="chat-panel"><div class="chat-head"><div class="assistant-avatar">${icon('spark',21)}</div><div class="assistant-label"><strong>Haven Assistant</strong><span><i class="status-dot"></i>${state.mode==='demo'?'Document search preview':'Connected to your workspace'}</span></div><button class="icon-btn" data-action="export" aria-label="Export conversation" title="Export conversation">${icon('download',18)}</button></div><div class="context-bar"><span>${icon('link',14)} In conversation about</span><select id="property-select" aria-label="Selected property">${state.properties.map(x=>`<option value="${esc(x.id)}" ${x.id===state.property?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div><div class="conversation" id="conversation" aria-live="polite">${messages.length?messages.map(messageHTML).join(''):welcomeHTML(p)}</div><div class="composer-wrap">${state.recording?'<div class="recording-status"><span class="pulse-dot"></span> Listening… pause to send, or tap the microphone to finish.</div>':''}<form id="chat-form" class="composer"><textarea id="question" aria-label="Ask about this property" placeholder="Ask anything about ${esc(p?.name||'this property')}…" rows="1" maxlength="4000" ${state.busy?'disabled':''}></textarea><div class="composer-controls"><button type="button" class="mic-btn ${state.recording?'recording':''}" data-action="mic" aria-label="${state.recording?'Finish recording':'Start voice conversation'}" title="Voice conversation">${icon(state.recording?'stop':'mic',19)}</button><button type="${state.busy?'button':'submit'}" class="send-btn" ${state.busy?'data-action="stop"':''} aria-label="${state.busy?'Stop response':'Send question'}">${icon(state.busy?'stop':'up',18)}</button></div></form><div class="composer-caption"><span>${icon('shield',12)} ${state.mode==='demo'?'Browser search · exact document excerpts · no LLM connected':'Answers grounded in your property documents'}</span><button class="voice-toggle ${state.voice?'on':''}" data-action="voice" aria-label="Toggle spoken replies">${icon('volume',13)} ${state.voice?'Voice on':'Voice off'}</button></div></div></section><aside class="context-column">${focusCard(p)}<section class="context-documents"><div class="section-title"><h3>Property knowledge</h3><span>${docCount(state.property)} doc${docCount(state.property)===1?'':'s'}</span></div>${state.documents.filter(d=>d.property_id===state.property).slice(0,3).map(d=>`<button class="document-mini" data-doc="${esc(d.id)}"><span class="doc-icon">${icon('file',17)}</span><span><strong>${esc(shortName(d.name))}</strong><small>${esc(d.kind)} · ${Array.isArray(d.pages)?d.pages.length:d.pages} page${(Array.isArray(d.pages)?d.pages.length:d.pages)===1?'':'s'}</small></span>${icon('chevron',13)}</button>`).join('')||'<p class="muted empty-small">Add a document to start asking questions.</p>'}<button class="text-link" data-nav="knowledge">Open knowledge base ${icon('arrow',14)}</button></section><div class="evidence-note">${icon('book',18)}<p><strong>Clarity, with receipts.</strong>Open a source citation to see exactly where an answer comes from.</p></div></aside></div><div class="trust-row"><span>${icon('shield',16)} Local-first by design</span><span>${icon('file',16)} Evidence you can open</span><span>${icon('mic',16)} Type it. Or talk it through.</span></div>`;}
function welcomeHTML(p){return `<div class="welcome"><div class="orb"><span class="orb-ring r1"></span><span class="orb-ring r2"></span><span class="orb-core">${icon('spark',36)}</span><span class="orb-speck s1"></span><span class="orb-speck s2"></span></div><span class="welcome-kicker">A LITTLE CLARITY STARTS HERE</span><h2>Less searching.<br>More understanding.</h2><p>Your leases, listings, and community rules.<br>One thoughtful conversation.</p><div class="suggestions">${[['file','What is the rent and security deposit?','Understand the essentials'],['heart','Are pets allowed here?','Make room for everyone'],['clock','What is the notice period?','Know where you stand'],['grid','What are the parking rules?','Get the everyday details']].map(([ic,q,label])=>`<button class="suggestion" data-question="${esc(q)}"><span>${icon(ic,17)}</span><div><strong>${esc(q)}</strong><small>${label}</small></div>${icon('arrow',14)}</button>`).join('')}</div></div>`;}
function shortName(name){return name.replace(/\.\w+$/,'').replace(/^.*? — /,'');}
function focusCard(p){if(!p)return '';return `<section class="focus-card"><div class="property-image"><img src="${esc(p.image)}" alt="Illustrative residential architecture" loading="eager"><span class="image-tag">${p.sample?'SAMPLE PROPERTY':'YOUR PROPERTY · ILLUSTRATIVE IMAGE'}</span><button class="favorite ${state.favorites.includes(p.id)?'selected':''}" data-favorite="${esc(p.id)}" aria-label="${state.favorites.includes(p.id)?'Remove from':'Add to'} favorites">${icon('heart',17)}</button></div><div class="focus-body"><span class="eyebrow">IN FOCUS</span><h2>${esc(p.name)}</h2><p class="location">${icon('pin',13)} ${esc(p.location)}</p><div class="property-specs"><span>${icon('bed',15)} ${p.beds} bed${p.beds===1?'':'s'}</span><span>${icon('area',14)} ${Number(p.area).toLocaleString()} sq ft</span></div><div class="price-row"><div><strong>${money(p.rent)}</strong><span> / month</span></div><button class="round-arrow" data-property="${esc(p.id)}" aria-label="View ${esc(p.name)}">${icon('arrow',18)}</button></div></div></section>`;}
function messageHTML(m,index){const content=esc(m.text||'').replace(/\[(S\d+)\]/g,(_,s)=>`<button class="citation" data-source="${s}" data-message="${index}">${icon('file',11)} ${s}</button>`).replace(/\n/g,'<br>');return `<article class="message ${m.role}"><span class="message-avatar">${m.role==='user'?'P':icon('spark',15)}</span><div class="message-content"><div class="message-author">${m.role==='user'?'You':'Haven'} ${m.mode?`<span>${m.mode==='extractive'?'Document excerpts':m.mode==='no_evidence'?'No supporting source':'AI response · verify sources'}</span>`:''}</div><div class="message-text">${content||'<span class="thinking">Reading your documents<span>…</span></span>'}</div>${m.sources?.length?`<div class="source-strip">${m.sources.map(s=>`<button data-source="${esc(s.label)}" data-message="${index}">${icon('file',12)} ${esc(shortName(s.name))} <span>p. ${s.page}</span></button>`).join('')}</div>`:''}</div></article>`;}
function propertiesView(){const shown=state.properties.filter(p=>(state.beds==='all'||state.beds==='saved'&&state.favorites.includes(p.id)||String(p.beds)===state.beds)&&`${p.name} ${p.location}`.toLowerCase().includes(state.query.toLowerCase()));return `${header('PLACES, WITH PERSPECTIVE','A place for every possibility.','Explore your properties and the knowledge that makes each one yours.','<button class="primary-btn" data-action="add-property">'+icon('plus',17)+' Add property</button>')}<div class="toolbar"><div class="filters">${[['all','All properties'],['1','1 bedroom'],['2','2 bedrooms'],['3','3 bedrooms'],['saved','Saved']].map(([v,t])=>`<button class="filter ${state.beds===v?'selected':''}" data-beds="${v}">${t}</button>`).join('')}</div><label class="search-field">${icon('search',17)}<input id="property-search" placeholder="Search name or location" value="${esc(state.query)}" aria-label="Search properties"></label></div><p class="data-note">${state.mode==='demo'?'Sample properties are fictional. Add your own property to build your workspace.':'Property details are entered by you; listing availability is not independently verified.'}</p><div class="property-grid">${shown.map(p=>`<article class="property-card">${focusCard(p)}<div class="card-bottom"><span>${icon('file',14)} ${docCount(p.id)} document${docCount(p.id)===1?'':'s'}</span><button class="text-link" data-ask-property="${esc(p.id)}">Ask Haven ${icon('arrow',14)}</button></div></article>`).join('')||empty('No properties found','Try another filter or add a property.')}</div>`;}
function knowledgeView(){const shown=state.documents.filter(d=>(state.docFilter==='all'||d.property_id===state.docFilter)&&`${d.name} ${d.kind}`.toLowerCase().includes(state.query.toLowerCase()));return `${header('THE KNOWLEDGE BEHIND THE ANSWERS','The details make the difference.','Keep your leases, property information, and community rules in one place.','<button class="primary-btn" data-action="upload">'+icon('upload',17)+' Add documents</button>')}<div class="knowledge-stats"><div><span class="stat-icon">${icon('file',21)}</span><strong>${state.documents.length}</strong><span>Documents in your workspace</span></div><div><span class="stat-icon">${icon('home',21)}</span><strong>${state.properties.length}</strong><span>Properties, kept separate</span></div><div><span class="stat-icon">${icon('shield',21)}</span><strong>${state.mode==='demo'?'In browser':'On device'}</strong><span>${state.mode==='demo'?'Saved on this browser':'Stored by your local backend'}</span></div></div><div class="document-table panel"><div class="table-toolbar"><label class="search-field">${icon('search',17)}<input id="doc-search" placeholder="Search documents" value="${esc(state.query)}" aria-label="Search documents"></label><select id="doc-filter" aria-label="Filter by property"><option value="all">All properties</option>${state.properties.map(p=>`<option value="${esc(p.id)}" ${state.docFilter===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></div><div class="table-scroll"><table><thead><tr><th>Document</th><th>Property</th><th>Type</th><th>Pages</th><th><span class="sr-only">Actions</span></th></tr></thead><tbody>${shown.map(d=>`<tr><td><button class="document-name" data-doc="${esc(d.id)}"><span class="doc-icon">${icon('file',19)}</span><span><strong>${esc(d.name)}</strong><small>${state.mode==='demo'?'Available to browser search':'Stored locally'}</small></span></button></td><td>${esc(prop(d.property_id)?.name||'Unknown')}</td><td><span class="type-chip">${esc(d.kind)}</span></td><td>${Array.isArray(d.pages)?d.pages.length:d.pages}</td><td><button class="icon-btn" data-delete-doc="${esc(d.id)}" aria-label="Delete ${esc(d.name)}">${icon('trash',16)}</button></td></tr>`).join('')||'<tr><td colspan="5">No matching documents. Add a document to get started.</td></tr>'}</tbody></table></div><div class="table-note">${icon('shield',14)} ${state.mode==='demo'?'TXT and Markdown work in this preview. PDF extraction is available in the local app.':'PDF, TXT and Markdown · 10 MB per file · scanned PDFs need OCR first.'}</div></div><button class="upload-zone" data-action="upload">${icon('upload',27)}<strong>More context. Better conversations.</strong><span>Add a lease or property document to your workspace</span></button>`;}
function activityView(){const traces=state.traces;const mean=traces.length?Math.round(traces.reduce((a,t)=>a+t.latency_ms,0)/traces.length):null;return `${header('A CLEARER VIEW UNDER THE HOOD','Every answer has a journey.','Inspect real response times, retrieval results, and the mode behind each answer.','<button class="subtle-btn" data-action="refresh">'+icon('activity',16)+' Refresh</button>')}<div class="knowledge-stats"><div><span class="stat-icon">${icon('activity',21)}</span><strong>${traces.length}</strong><span>Recorded turns</span></div><div><span class="stat-icon">${icon('clock',21)}</span><strong>${mean===null?'—':mean+' ms'}</strong><span>${state.mode==='demo'?'Average browser search time':'Average answer time'}</span></div><div><span class="stat-icon">${icon('book',21)}</span><strong>${traces.filter(t=>t.sources>0).length}</strong><span>Turns with retrieved sources</span></div></div><section class="panel"><div class="panel-heading"><h3>Recent conversations</h3><span class="muted">${state.mode==='demo'?'Browser events':'Local traces'} · latest 100</span></div>${traces.length?`<div class="table-scroll"><table><thead><tr><th>Turn</th><th>Property</th><th>Mode</th><th>Sources</th><th>Time</th></tr></thead><tbody>${traces.slice(0,100).map(t=>`<tr><td><strong>${new Date(t.created*1000).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}</strong><small class="trace-id">${esc(t.id)}</small></td><td>${esc(prop(t.property_id)?.name||t.property_id)}</td><td><span class="type-chip">${esc(t.mode)}</span></td><td>${t.sources}</td><td>${t.latency_ms} ms</td></tr>`).join('')}</tbody></table></div>`:empty('Nothing to inspect just yet','Ask Haven a question. Your first retrieval trace will appear here.')}</section><div class="info-banner">${icon('activity',20)}<p><strong>Measure what actually happened.</strong>These are measured events, not estimated scores. Citation presence does not prove factual correctness. The local project includes Phoenix tracing and a retrieval evaluation script.</p></div>`;}
function settingsView(){const h=state.health;return `${header('YOUR WORKSPACE, YOUR WAY','Keep it close to home.','Run the AI on your own machine. Connect optional services only when you choose.')}<div class="settings-grid"><section class="panel setup-panel"><div class="section-title"><h3>${icon('code',20)} Bring Haven to your laptop</h3><span class="type-chip">No paid API</span></div><p>Download the complete project, install Python 3.11 or 3.12 and Ollama, then run the setup for your system.</p><div class="setup-steps"><div><b>1</b><span><strong>Get the project</strong><small>FastAPI backend, voice transport, retrieval, tests, and this interface.</small></span><a class="icon-btn" href="downloads/Haven-Realty-Source.zip" download aria-label="Download project">${icon('download',18)}</a></div><div><b>2</b><span><strong>Download the local language model</strong><code>ollama pull llama3.2:3b</code></span></div><div><b>3</b><span><strong>Start your workspace</strong><small>Windows: run start-windows.cmd<br>macOS: run bash start-macos.sh</small></span></div></div><a class="primary-btn full" href="downloads/Haven-Realty-Source.zip" download>${icon('download',17)} Download the project</a><p class="fine-print">First setup downloads dependencies and models. Local performance depends on your RAM and processor. Open http://127.0.0.1:8000 for the most reliable microphone connection.</p></section><section class="panel connection-panel"><div class="section-title"><h3>${icon('link',20)} Backend connection</h3><span class="status-pill">${state.mode==='demo'?'Preview mode':'Connected'}</span></div><p>The hosted preview searches sample text in your browser. Connect your running backend to enable local AI, PDFs, and speech recognition.</p><form id="connect-form"><label>Backend URL<input name="base" type="url" required value="${esc(state.base||'http://127.0.0.1:8000')}" placeholder="http://127.0.0.1:8000"></label><label>Local access token <span class="muted">(if configured)</span><input name="token" type="password" autocomplete="off" placeholder="From HAVEN_API_TOKEN in your .env"></label><div class="button-row"><button class="primary-btn" type="submit">${icon('link',16)} Test & connect</button>${state.mode==='live'?'<button class="subtle-btn" data-action="disconnect" type="button">Use preview</button>':''}</div></form><p class="fine-print">If your browser blocks access from this HTTPS preview to localhost, open the local app directly. A public connection requires HTTPS/WSS and an access token.</p>${h?`<div class="connection-details"><span>Model <strong>${esc(h.model)} · ${h.model_ready?'ready':'not verified / not ready'}</strong></span><span>Search <strong>${esc(h.retrieval)}</strong></span><span>Memory <strong>${esc(h.memory)}</strong></span><span>Voice <strong>${esc(h.tts)} · STT ${esc(h.stt)}</strong></span><span>Phoenix <strong>${esc(h.phoenix)}</strong></span></div>`:''}</section></div><section class="panel stack-panel"><div class="section-title"><h3>The open stack</h3><span class="muted">Configured in your local .env</span></div><div class="stack-grid">${[['Local intelligence','Ollama','No API key. Runs on your machine.'],['Speech recognition','faster-whisper','16 kHz audio over WebSockets.'],['Document search','MiniLM + FAISS','Property-scoped hybrid retrieval.'],['Memory & tracing','SQLite · Redis · Phoenix','Start simple. Add services when needed.']].map(([a,b,c])=>`<div><small>${a}</small><strong>${b}</strong><p>${c}</p></div>`).join('')}</div><div class="table-note">${icon('help',15)} Groq is an optional, rate-limited cloud service. Edge TTS uses an online service. Neither is needed for the default local workflow.</div></section>`;}
function empty(title,subtitle){return `<div class="empty-state">${icon('book',30)}<h3>${title}</h3><p>${subtitle}</p></div>`;}
function openModal(title,body,wide=false){const d=$('#modal');d.className=wide?'wide':'';d.innerHTML=`<div class="modal-head"><h2>${esc(title)}</h2><button class="icon-btn" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button></div><div class="modal-body">${body}</div>`;if(!d.open)d.showModal();}
function scrollChat(){const c=$('#conversation');if(c)c.scrollTop=(state.chats[state.property]||[]).length?c.scrollHeight:0;}
function updateConversation(){if(state.view!=='assistant')return;$('#conversation').innerHTML=(state.chats[state.property]||[]).map(messageHTML).join('');scrollChat();}
async function api(path,options={}){const headers={...(options.headers||{})};const token=sessionStorage.getItem('haven-token');if(token)headers.Authorization='Bearer '+token;const r=await fetch(state.base+path,{...options,headers,signal:AbortSignal.timeout(15000)});if(!r.ok){let msg='Request failed';try{const j=await r.json();msg=typeof j.detail==='string'?j.detail:msg;}catch{}throw new Error(msg);}return r.json();}
async function connect(base,token){let url;try{url=new URL(base);}catch{throw new Error('Enter a valid backend URL.');}if(!['https:','http:'].includes(url.protocol)||(url.protocol==='http:'&&!['localhost','127.0.0.1','[::1]'].includes(url.hostname)))throw new Error('Use localhost over HTTP, or an HTTPS backend.');const oldBase=state.base,oldToken=sessionStorage.getItem('haven-token');state.base=url.origin;if(token)sessionStorage.setItem('haven-token',token);else sessionStorage.removeItem('haven-token');try{const h=await api('/api/health');const [properties,documents,traces]=await Promise.all([api('/api/properties'),api('/api/documents'),api('/api/traces')]);stopAll();ws?.close();ws=null;wsPromise=null;Object.assign(state,{mode:'live',health:h,properties,documents,traces,chats:{},session:uid(),busy:false});if(!properties.some(p=>p.id===state.property))state.property=properties[0]?.id||'';render();toast(h.model_ready?'Local backend and model are ready.':'Backend connected. Check model readiness in Settings.');}catch(e){state.base=oldBase;if(oldToken)sessionStorage.setItem('haven-token',oldToken);else sessionStorage.removeItem('haven-token');throw e;}}
async function socket(){if(ws?.readyState===WebSocket.OPEN)return ws;if(wsPromise)return wsPromise;wsPromise=new Promise((resolve,reject)=>{const url=state.base.replace(/^http/,'ws')+'/ws';const current=new WebSocket(url);ws=current;let settled=false;const timer=setTimeout(()=>{current.close();reject(new Error('Voice connection timed out.'));},10000);current.onopen=()=>current.send(JSON.stringify({type:'auth',session:state.session,token:sessionStorage.getItem('haven-token')||''}));current.onmessage=event=>{const message=JSON.parse(event.data);if(message.type==='ready'){settled=true;clearTimeout(timer);resolve(current);}else handleEvent(message);};current.onerror=()=>{clearTimeout(timer);reject(new Error('Could not connect to the local WebSocket.'));};current.onclose=()=>{clearTimeout(timer);if(ws!==current)return;ws=null;wsPromise=null;if(!settled)reject(new Error('WebSocket access denied or connection closed.'));if(state.busy||state.recording){stopAll();state.busy=false;if(state.current&&!state.current.text)state.current.text='The connection closed. Please reconnect and try again.';render();}};});return wsPromise;}
function chatList(){return state.chats[state.property]??=([]);}
async function sendQuestion(question){question=question.trim();if(!question||state.busy)return;stopPlayback();state.busy=true;chatList().push({role:'user',text:question});const answer={role:'assistant',text:'',sources:[]};chatList().push(answer);state.current=answer;render();if(state.mode==='demo'){const start=performance.now();const result=extractiveAnswer(question,state.documents,state.property);Object.assign(answer,result);state.traces.unshift({id:uid().slice(0,12),property_id:state.property,mode:result.sources.length?'extractive':'no_evidence',latency_ms:Math.max(1,Math.round(performance.now()-start)),sources:result.sources.length,created:Date.now()/1000});state.busy=false;save();render();if(state.voice)speak(answer.text);return;}try{const s=await socket();if(state.current!==answer||!state.busy)return;s.send(JSON.stringify({type:'chat',text:question,property_id:state.property,voice:state.voice}));}catch(e){answer.text=e.message;state.busy=false;render();toast(e.message);}}
function handleEvent(e){const answer=state.current;if(e.type==='sources'&&answer){answer.sources=e.sources;updateConversation();}if(e.type==='token'&&answer){answer.text+=e.text;updateConversation();}if(e.type==='replace'&&answer){answer.text=e.text;updateConversation();}if(e.type==='done'&&answer){Object.assign(answer,{text:e.text,sources:e.sources,mode:e.mode});state.traces.unshift(e.trace);state.busy=false;render();}if(e.type==='transcript'){const list=chatList();if(list.length&&list[list.length-2]?.voicePending)list[list.length-2]={role:'user',text:e.text};else list.splice(-1,0,{role:'user',text:e.text});updateConversation();}if(e.type==='speak')speak(e.text);if(e.type==='audio'){stopPlayback();activeAudio=new Audio(`data:${e.mime};base64,${e.data}`);activeAudio.play().catch(()=>toast('Tap the speaker to allow spoken replies.'));}if(e.type==='notice')toast(e.message);if(e.type==='error'){state.busy=false;if(answer&&!answer.text)answer.text=e.message;stopCapture(false);render();toast(e.message);}if(e.type==='cancelled'){state.busy=false;render();}}
function stopPlayback(){window.speechSynthesis?.cancel();if(activeAudio){activeAudio.pause();activeAudio=null;}}
function speak(text){if(!window.speechSynthesis)return toast('Your browser does not support spoken replies.');stopPlayback();const utterance=new SpeechSynthesisUtterance(text.replace(/\[S\d+\]/g,''));const voices=speechSynthesis.getVoices();const local=voices.find(v=>v.localService&&v.lang.startsWith('en-IN'))||voices.find(v=>v.localService&&v.lang.startsWith('en'));if(!local)return toast('No installed English voice was found. Install a system voice, or enable Edge TTS in the local app.');utterance.voice=local;utterance.rate=.98;speechSynthesis.speak(utterance);}
async function startCapture(){if(state.recording)return stopCapture(true);if(state.mode!=='live'){openModal('Talk to Haven',`<div class="voice-explain"><span class="large-icon">${icon('mic',30)}</span><h3>Your voice. Your local AI.</h3><p>Voice input is available when the local backend is running. Your microphone audio goes to faster-whisper on your machine.</p><p>You can try document search by typing now, or open setup to connect your backend.</p><button class="primary-btn" data-action="voice-setup">Open local setup ${icon('arrow',16)}</button></div>`);return;}if(!navigator.mediaDevices?.getUserMedia||!window.AudioWorkletNode){toast('Microphone capture needs localhost or HTTPS and a supported browser.');return;}try{stopAll();if(ws?.readyState===1)ws.send(JSON.stringify({type:'cancel'}));const s=await socket();micStream=await navigator.mediaDevices.getUserMedia({audio:{channelCount:1,echoCancellation:true,noiseSuppression:true}});audioContext=new AudioContext();await audioContext.resume();await audioContext.audioWorklet.addModule('pcm-worklet.js');worklet=new AudioWorkletNode(audioContext,'pcm-capture');const source=audioContext.createMediaStreamSource(micStream);source.connect(worklet);const mute=audioContext.createGain();mute.gain.value=0;worklet.connect(mute);mute.connect(audioContext.destination);heardSpeech=false;lastSpeech=performance.now();const began=lastSpeech;worklet.port.onmessage=({data})=>{if(!state.recording)return;if(s.bufferedAmount>256000){stopCapture(false);toast('Audio connection is too slow. Try again.');return;}s.send(data.pcm);if(data.rms>.015){heardSpeech=true;lastSpeech=performance.now();}};s.send(JSON.stringify({type:'audio_start',sample_rate:16000,property_id:state.property}));state.recording=true;state.busy=false;render();captureTimer=setInterval(()=>{const now=performance.now();if((heardSpeech&&now-lastSpeech>1100)||now-began>25000)stopCapture(true);},200);}catch(e){stopCapture(false);state.busy=false;render();toast(e.name==='NotAllowedError'?'Microphone permission was denied. Allow access in your browser, or type your question.':e.message);}}
function stopCapture(send){const was=state.recording;state.recording=false;clearInterval(captureTimer);worklet?.disconnect();worklet=null;micStream?.getTracks().forEach(t=>t.stop());micStream=null;if(audioContext){audioContext.close().catch(()=>{});audioContext=null;}if(was&&ws?.readyState===1){if(send){chatList().push({role:'user',text:'Transcribing your voice…',voicePending:true});state.current={role:'assistant',text:'',sources:[]};chatList().push(state.current);state.busy=true;ws.send(JSON.stringify({type:'audio_end'}));}else ws.send(JSON.stringify({type:'cancel'}));}if(was)render();}
function stopAll(){stopPlayback();stopCapture(false);}
async function showDocument(id){try{let d=state.documents.find(d=>d.id===id);if(state.mode==='live')d=await api('/api/documents/'+encodeURIComponent(id));if(!d)return;const excerpts=d.excerpts||d.pages.map((text,i)=>({page:i+1,text}));openModal(d.name,`<div class="document-context"><span class="type-chip">${esc(d.kind)}</span><span>${esc(prop(d.property_id)?.name)}</span></div><div class="document-preview">${excerpts.map(s=>`<section><span class="page-label">PAGE ${s.page}</span><p>${esc(s.text).replace(/\n/g,'<br>')}</p></section>`).join('')}</div>`,true);}catch(e){toast(e.message);}}
function uploadModal(){openModal('Add to your knowledge base',`<form id="upload-form"><p class="form-intro">Choose a property so its documents stay in the right conversation.</p><label>Property<select name="property_id">${state.properties.map(p=>`<option value="${esc(p.id)}" ${p.id===state.property?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><label>Document type<select name="kind"><option>Lease</option><option>Community rules</option><option>Property details</option><option>Other</option></select></label><label class="file-drop">${icon('upload',25)}<strong>Choose documents</strong><span>${state.mode==='demo'?'TXT or Markdown · up to 2 MB each':'PDF, TXT or Markdown · up to 10 MB each'}</span><input type="file" name="files" multiple required accept="${state.mode==='demo'?'.txt,.md':'.txt,.md,.pdf'}"></label><p class="fine-print">${state.mode==='demo'?'Files are saved in this browser. Use the local app to search PDFs.':'Text is extracted and stored on your backend. Encrypted and scanned PDFs need preparation first.'}</p><button class="primary-btn full" type="submit">${icon('plus',16)} Add documents</button><p id="upload-status" role="status"></p></form>`);}
function addPropertyModal(){openModal('Make room for a new property',`<form id="property-form"><label>Property name<input name="name" required maxlength="100" placeholder="e.g. My Whitefield apartment"></label><label>Location<input name="location" required maxlength="150" placeholder="Neighbourhood, city"></label><div class="form-columns"><label>Bedrooms<input name="beds" type="number" min="0" max="30" value="2" required></label><label>Bathrooms<input name="baths" type="number" min="0" max="30" value="2" required></label></div><div class="form-columns"><label>Area (sq ft)<input name="area" type="number" min="1" max="1000000" required></label><label>Monthly rent (₹)<input name="rent" type="number" min="0" max="100000000" required></label></div><label>Description<textarea name="description" maxlength="1000" rows="3" placeholder="A few details about this property"></textarea></label><p class="fine-print">The card uses an illustrative image. Upload property documents after adding it.</p><button class="primary-btn full">${icon('plus',16)} Add property</button></form>`);}
function propertyModal(id){const p=prop(id);openModal(p.name,`<img class="modal-property-image" src="${esc(p.image)}" alt="Illustrative residential architecture"><p class="location">${icon('pin',15)} ${esc(p.location)}</p><p>${esc(p.description)}</p><div class="detail-grid"><span>Monthly rent<strong>${money(p.rent)}</strong></span><span>Bedrooms<strong>${p.beds}</strong></span><span>Bathrooms<strong>${p.baths}</strong></span><span>Floor area<strong>${p.area} sq ft</strong></span></div><p class="fine-print">${p.sample?'Fictional sample property. Pricing, rules, and availability are for demonstration only.':'Details entered by you. The image is illustrative; availability is not verified.'}</p><button class="primary-btn full" data-ask-property="${esc(p.id)}">Ask about this property ${icon('arrow',16)}</button>`);}
function guide(){openModal('Welcome to your Haven',`<div class="guide-intro"><span class="large-icon">${icon('home',30)}</span><h3>Start with a question.<br>Follow it to the source.</h3></div><ol class="guide-list"><li><strong>Choose a property</strong><p>Each conversation stays scoped to that property’s documents.</p></li><li><strong>Ask about the details</strong><p>Try rent, pets, deposits or notice periods. Click citations to inspect the source.</p></li><li><strong>Make it your own</strong><p>Add a property and text documents. Run the local project for PDF search, AI-generated answers and microphone input.</p></li></ol><div class="info-banner compact"><p>The hosted preview uses browser document search. It does not pretend to run an AI model. Sample properties and documents are fictional.</p></div><button class="primary-btn full" data-action="close-modal">Make yourself at home ${icon('arrow',16)}</button>`);}
function downloadText(name,text){const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
document.addEventListener('click',async event=>{
 const b=event.target.closest('button,a[data-nav]');if(!b)return;
 try{
 if(b.dataset.nav){event.preventDefault();changeView(b.dataset.nav);return;}
 if(b.dataset.question){sendQuestion(b.dataset.question);return;}
 if(b.dataset.favorite){const id=b.dataset.favorite;state.favorites=state.favorites.includes(id)?state.favorites.filter(x=>x!==id):[...state.favorites,id];save();render();return;}
 if(b.dataset.property){propertyModal(b.dataset.property);return;}
 if(b.dataset.askProperty){stopAll();ws?.readyState===1&&ws.send(JSON.stringify({type:'cancel'}));state.busy=false;state.property=b.dataset.askProperty;$('#modal').close();save();changeView('assistant');return;}
 if(b.dataset.doc){await showDocument(b.dataset.doc);return;}
 if(b.dataset.source){const s=state.chats[state.property]?.[Number(b.dataset.message)]?.sources?.find(s=>s.label===b.dataset.source);if(s)openModal('The source behind the answer',`<div class="source-heading">${icon('file',22)}<div><strong>${esc(s.name)}</strong><p>Page ${s.page} · ${esc(prop()?.name)}</p></div><span class="type-chip">${esc(s.label)}</span></div><blockquote class="source-quote">${esc(s.text).replace(/\n/g,'<br>')}</blockquote><p class="fine-print">This is the retrieved excerpt. Compare it with the answer to check that the claim is supported.</p>`);return;}
 if(b.dataset.beds){state.beds=b.dataset.beds;render();return;}
 if(b.dataset.deleteDoc){const d=state.documents.find(d=>d.id===b.dataset.deleteDoc);openModal('Remove this document?',`<p>Remove <strong>${esc(d.name)}</strong> from search? Existing conversation text will remain until you start a new conversation.</p><div class="button-row"><button class="danger-btn" data-confirm-delete="${esc(d.id)}">Remove document</button><button class="subtle-btn" data-action="close-modal">Keep document</button></div>`);return;}
 if(b.dataset.confirmDelete){if(state.mode==='live')await api('/api/documents/'+encodeURIComponent(b.dataset.confirmDelete),{method:'DELETE'});state.documents=state.documents.filter(d=>d.id!==b.dataset.confirmDelete);save();$('#modal').close();render();toast('Document removed from search.');return;}
 const action=b.dataset.action;
 if(action==='menu')$('.sidebar').classList.toggle('mobile-open');
 if(action==='guide')guide();
 if(action==='close-modal')$('#modal').close();
 if(action==='upload')uploadModal();
 if(action==='add-property')addPropertyModal();
 if(action==='voice-setup'){$('#modal').close();changeView('settings');}
 if(action==='mic')await startCapture();
 if(action==='voice'){state.voice=!state.voice;if(!state.voice)stopPlayback();else{toast('Spoken replies enabled when an installed voice is available.');const recent=[...(state.chats[state.property]||[])].reverse().find(m=>m.role==='assistant');if(recent)speak(recent.text);}render();}
 if(action==='stop'){stopAll();if(ws?.readyState===1)ws.send(JSON.stringify({type:'cancel'}));state.busy=false;if(state.current&&!state.current.text)state.current.text='Response stopped.';render();}
 if(action==='new-chat'){stopAll();if(ws?.readyState===1)ws.send(JSON.stringify({type:'cancel'}));if(state.mode==='live')await api('/api/sessions/'+encodeURIComponent(state.session),{method:'DELETE'});state.chats[state.property]=[];state.session=uid();ws?.close();ws=null;wsPromise=null;state.busy=false;state.current=null;save();render();}
 if(action==='export'){const messages=state.chats[state.property]||[];if(!messages.length){toast('Start a conversation first.');return;}downloadText('Haven-Conversation.txt',`Haven — ${prop()?.name}\n${state.mode==='demo'?'Browser document-search preview':'Local AI workspace'}\n\n`+messages.map(m=>`${m.role==='user'?'You':'Haven'}: ${m.text}\n${(m.sources||[]).map(s=>`[${s.label}] ${s.name}, page ${s.page}\n${s.text}`).join('\n')}`).join('\n\n'));}
 if(action==='refresh'){if(state.mode==='live')state.traces=await api('/api/traces');render();toast('Activity is up to date.');}
 if(action==='disconnect'){stopAll();ws?.close();ws=null;wsPromise=null;state.mode='demo';state.health=null;state.base='';state.busy=false;state.current=null;const data=await initStorage();const fixture=await (await fetch('assets/sample-data.json')).json();Object.assign(state,data||{...fixture,chats:{},traces:[],favorites:[],property:'canopy'});render();toast('Switched to your browser workspace.');}
 }catch(e){toast(e.message);}
});
document.addEventListener('change',event=>{const el=event.target;if(el.id==='property-select'){stopAll();if(ws?.readyState===1)ws.send(JSON.stringify({type:'cancel'}));state.property=el.value;state.busy=false;state.current=null;save();render();}if(el.id==='doc-filter'){state.docFilter=el.value;render();}});
document.addEventListener('input',event=>{if(['property-search','doc-search'].includes(event.target.id)){const id=event.target.id,pos=event.target.selectionStart;state.query=event.target.value;render();const input=$('#'+id);input.focus();input.setSelectionRange(pos,pos);}});
document.addEventListener('keydown',event=>{if(event.target.id==='question'&&event.key==='Enter'&&!event.shiftKey){event.preventDefault();sendQuestion(event.target.value);}});
document.addEventListener('submit',async event=>{
 event.preventDefault();const form=event.target;
 if(form.id==='chat-form'){sendQuestion($('#question').value);return;}
 const button=form.querySelector('button[type="submit"]')||form.querySelector('button');if(button)button.disabled=true;
 try{
 if(form.id==='connect-form'){const data=new FormData(form);await connect(data.get('base'),data.get('token'));}
 if(form.id==='property-form'){const data=Object.fromEntries(new FormData(form));for(const k of ['beds','baths','area','rent'])data[k]=Number(data[k]);data.type='Apartment';const p=state.mode==='live'?await api('/api/properties',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}):{...data,id:uid(),image:'assets/canopy.jpg',sample:false};state.properties.push(p);state.property=p.id;state.beds='all';state.query='';save();$('#modal').close();render();toast('Property added. Add its documents to start a conversation.');}
 if(form.id==='upload-form'){
 const fd=new FormData(form),files=[...form.elements.files.files],property_id=fd.get('property_id'),kind=fd.get('kind');let added=0;
 for(const file of files){$('#upload-status').textContent=`Reading ${file.name}…`;if(state.mode==='live'){const body=new FormData();body.append('file',file);body.append('property_id',property_id);body.append('kind',kind);const d=await api('/api/documents',{method:'POST',body});state.documents.unshift({...d,pages:d.pages});}else{if(!/\.(txt|md)$/i.test(file.name))throw new Error('Use TXT or Markdown in the browser preview. PDFs work in the local app.');if(file.size>2*1024*1024)throw new Error('Preview documents must be 2 MB or smaller.');const text=await file.text();if(!text.trim())throw new Error('The file has no readable text.');state.documents.unshift({id:uid(),name:file.name,property_id,kind,pages:[text]});}added++;save();}
 state.docFilter=property_id;state.query='';$('#modal').close();render();toast(`${added} document${added===1?'':'s'} added to your knowledge base.`);
 }
 }catch(e){toast(e.message);if($('#upload-status'))$('#upload-status').textContent=e.message;}finally{if(button)button.disabled=false;}
});
window.addEventListener('hashchange',()=>{const view=location.hash.slice(1);if(['assistant','properties','knowledge','activity','settings'].includes(view)&&state.view!==view){state.view=view;state.query='';render();}});
window.addEventListener('beforeunload',()=>{stopAll();ws?.close();});
$('#modal').addEventListener('click',event=>{if(event.target===$('#modal'))$('#modal').close();});
async function boot(){try{const fixture=await (await fetch('assets/sample-data.json')).json();const saved=await initStorage();Object.assign(state,saved||fixture);if(!state.properties.some(p=>p.id===state.property))state.property=state.properties[0]?.id;render();if(['127.0.0.1','localhost'].includes(location.hostname))try{await connect(location.origin,sessionStorage.getItem('haven-token')||'');}catch{toast('Local backend needs attention. Open Settings to connect.');}}catch{ $('#app').innerHTML='<div class="loading-screen">Could not load the workspace. Please refresh the page.</div>';}}
boot();
